    // Initialize x to zero
    x.resize(N, 0);

    // Create a HPX parallel for loop to compute the solution
    hpx::parallel::for_loop(0, N, [&](size_t i) {
        // Compute the sum of the products of the ith row of A and the corresponding elements of x and b
        double sum = 0;
        for (size_t j = 0; j < N; ++j) {
            sum += A[i * N + j] * x[j];
        }
        sum -= b[i];

        // Update the ith element of x
        x[i] = -sum / A[i * N + i];
    });
}

