void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
  // Initialize x to 0
  x.resize(N);
  std::fill(x.begin(), x.end(), 0);

  // Compute the diagonal of A
  std::vector<double> diag(N);
  for (size_t i = 0; i < N; ++i) {
    diag[i] = A[i * N + i];
  }

  // Compute the rest of the matrix
  std::vector<double> rest(N * N);
  for (size_t i = 0; i < N; ++i) {
    for (size_t j = 0; j < N; ++j) {
      if (i != j) {
        rest[i * N + j] = A[i * N + j];
      }
    }
  }

  // Compute the rest of the matrix in parallel
  hpx::future<std::vector<double>> rest_future = hpx::async([](std::vector<double> const& rest, size_t N) {
    std::vector<double> result(N * N);
    for (size_t i = 0; i < N; ++i) {
      for (size_t j = 0; j < N; ++j) {
        if (i != j) {
          result[i * N + j] = rest[i * N + j];
        }
      }
    }
    return result;
  }, rest, N);

  // Compute the diagonal of A in parallel
  hpx::future<std::vector<double>> diag_future = hpx::async([](std::vector<double> const& diag, size_t N) {
    std::vector<double> result(N);
    for (size_t i = 0; i < N; ++i) {
      result[i] = diag[i];
    }
    return result;
  }, diag, N);

  // Compute the rest of the matrix
  std::vector<double> rest_result = rest_future.get();

  // Compute the diagonal of A
  std::vector<double> diag_result = diag_future.get();

  // Compute the solution
  for (size_t i = 0; i < N; ++i) {
    x[i] = b[i];
    for (size_t j = 0; j < N; ++j) {
      if (i != j) {
        x[i] -= rest_result[i * N + j] * x[j];
      }
    }
    x[i] /= diag_result[i];
  }
}

