void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Create a vector of N parallel tasks
    std::vector<hpx::future<double>> results(N);

    // Compute the dot product of each row of A with b in parallel
    for (size_t i = 0; i < N; ++i) {
        results[i] = hpx::async([i, &A, &b, N]() {
            double sum = 0;
            for (size_t j = 0; j < N; ++j) {
                sum += A[i * N + j] * b[j];
            }
            return sum;
        });
    }

    // Wait for all the tasks to complete and store the results in x
    for (size_t i = 0; i < N; ++i) {
        x[i] = results[i].get();
    }
}

