void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
  // Initialize x to all zeros
  x.resize(N, 0);

  // Create a HPX parallel for loop to compute x
  hpx::parallel::for_loop(0, N, [&](size_t i) {
    // Compute the ith element of x
    double sum = 0;
    for (size_t j = 0; j < N; ++j) {
      sum += A[i * N + j] * x[j];
    }
    x[i] = (b[i] - sum) / A[i * N + i];
  });
}

