generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Create a vector of N tasks, one for each row of A
    std::vector<hpx::future<double>> tasks(N);

    // For each row of A, compute the dot product of that row with b
    for (size_t i = 0; i < N; ++i) {
        tasks[i] = hpx::async([&A, &b, i, N]() {
            double sum = 0;
            for (size_t j = 0; j < N; ++j) {
                sum += A[i * N + j] * b[j];
            }
            return sum;
        });
    }

    // Wait for all the tasks to complete and store the results in x
    for (size_t i = 0; i < N; ++i) {
        x[i] = tasks[i].get();
    }
}

