void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
  // Initialize x to all zeros
  std::fill(x.begin(), x.end(), 0.0);

  // Compute the diagonal of A
  std::vector<double> diag(N);
  for (size_t i = 0; i < N; ++i) {
    diag[i] = A[i * N + i];
  }

  // Compute the rest of the matrix
  std::vector<double> rest(N * N);
  for (size_t i = 0; i < N; ++i) {
    for (size_t j = 0; j < N; ++j) {
      if (i != j) {
        rest[i * N + j] = A[i * N + j];
      }
    }
  }

  // Compute the rest of the matrix in parallel
  hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
    for (size_t j = 0; j < N; ++j) {
      if (i != j) {
        rest[i * N + j] /= diag[i];
      }
    }
  });

  // Compute the diagonal of A in parallel
  hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
    diag[i] = 1.0 / diag[i];
  });

  // Compute the solution in parallel
  hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
    double sum = 0.0;
    for (size_t j = 0; j < N; ++j) {
      sum += rest[i * N + j] * x[j];
    }
    x[i] = (b[i] - sum) * diag[i];
  });
}

