generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Initialize x to all zeros
    std::fill(x.begin(), x.end(), 0);

    // Compute the transpose of A
    std::vector<double> At(N * N);
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            At[i * N + j] = A[j * N + i];
        }
    }

    // Compute the product of A and b
    std::vector<double> Ab(N);
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            Ab[i] += A[i * N + j] * b[j];
        }
    }

    // Compute the product of At and Ab in parallel
    std::vector<double> AtAb(N);
    hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
        for (size_t j = 0; j < N; ++j) {
            AtAb[i] += At[i * N + j] * Ab[j];
        }
    });

    // Compute the inverse of A
    std::vector<double> Ainv(N * N);
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            Ainv[i * N + j] = (i == j) ? 1 : 0;
        }
    }
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            if (i != j) {
                double factor = Ainv[j * N + i] / A[i * N + i];
                for (size_t k = 0; k < N; ++k) {
                    Ainv[j * N + k] -= factor * A[i * N + k];
                }
            }
        }
    }

    // Compute the product of Ainv and AtAb
    std::vector<double> AinvAtAb(N);
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            AinvAtAb[i] += Ainv[i * N + j] * AtAb[j];
        }
    }

    // Copy the result to x
    std::copy(AinvAtAb.begin(), AinvAtAb.end(), x.begin());
}

