    // Create a HPX parallel_for_each loop to compute the matrix multiplication.
    hpx::parallel::for_each(hpx::parallel::execution::par, 0, M, [&](size_t i) {
        for (size_t j = 0; j < N; ++j) {
            double sum = 0;
            for (size_t k = 0; k < K; ++k) {
                sum += A[i * K + k] * B[k * N + j];
            }
            C[i * N + j] = sum;
        }
    });
}

