void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    // Create HPX parallel execution policy
    hpx::parallel::execution::parallel_executor exec;

    // Compute the matrix multiplication in parallel
    hpx::parallel::for_each(exec, hpx::parallel::counting_iterator<size_t>(0), hpx::parallel::counting_iterator<size_t>(M * N), [&](size_t i) {
        size_t row = i / N;
        size_t col = i % N;
        double sum = 0;
        for (size_t k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[i] = sum;
    });
}

