void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    // Check that the vectors have the same size
    if (x.size() != y.size() || x.size() != z.size()) {
        throw std::invalid_argument("Vectors must have the same size");
    }

    // Compute the axpy operation in parallel using HPX
    hpx::parallel::for_each(hpx::parallel::execution::par, 0, x.size(), [&](int i) {
        z[i] = alpha * x[i] + y[i];
    });
}

