    for (size_t i = 0; i < M; ++i) {
        futures[i] = hpx::async([i, &A, &x, M, N]() {
            double sum = 0;
            for (size_t j = 0; j < N; ++j) {
                sum += A[i * N + j] * x[j];
            }
            return sum;
        });
    }
    for (size_t i = 0; i < M; ++i) {
        y[i] = futures[i].get();
    }
}

