        }
        return sum;
    };

    // Launch the parallel computations
    for (size_t i = 0; i < M; ++i) {
        results[i] = hpx::async(dot_product, i);
    }

    // Wait for the computations to complete and store the results in y
    for (size_t i = 0; i < M; ++i) {
        y[i] = results[i].get();
    }
}

