generated_output:
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    // Create a vector of futures to store the results of the parallel computations
    std::vector<hpx::future<double>> results(M);

    // Compute the dot product of each row of A with x in parallel
    for (size_t i = 0; i < M; ++i) {
        results[i] = hpx::async([=]() {
            double sum = 0;
            for (size_t j = 0; j < N; ++j) {
                sum += A[i * N + j] * x[j];
            }
            return sum;
        });
    }

    // Wait for all the futures to complete and store the results in y
    for (size_t i = 0; i < M; ++i) {
        y[i] = results[i].get();
    }
}

