#include <hpx/hpx_main.hpp>

/* Multiply the matrix A by the vector x. Store the results in the vector y.
   A is an MxN matrix, x has N elements, and y has M elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized. 
   Example:

   input: A=[[1, -1, 2], [0, -3, 1]] x=[2, 1, 0]
   output: y=[1, -3]
*/
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

generated_output:
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    hpx::future<void> futures[M];
    for (size_t i = 0; i < M; i++) {
        futures[i] = hpx::async([i, &A, &x, &y, N]() {
            double sum = 0;
            for (size_t j = 0; j < N; j++) {
                sum += A[i * N + j] * x[j];
            }
            y[i] = sum;
        });
    }
    hpx::wait_all(futures);
}

