    std::vector<hpx::future<double>> results(M);

    // Compute the dot product of each row of A with x in parallel
    for (size_t i = 0; i < M; ++i) {
        results[i] = hpx::async([i, &A, &x, N]() {
            double sum = 0;
            for (size_t j = 0; j < N; ++j) {
                sum += A[i * N + j] * x[j];
            }
            return sum;
        });
    }

    // Wait for all the computations to complete and store the results in y
    for (size_t i = 0; i < M; ++i) {
        y[i] = results[i].get();
    }
}

