#include <hpx/hpx_main.hpp>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal of A
   std::vector<double> diagonal(N, 0);
   for (auto const& element : A) {
      if (element.row == element.column) {
         diagonal[element.row] = element.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<std::vector<double>> offDiagonal(N, std::vector<double>(N, 0));
   for (auto const& element : A) {
      if (element.row != element.column) {
         offDiagonal[element.row][element.column] = element.value;
      }
   }

   // Compute the solution in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      double sum = 0;
      for (size_t j = 0; j < N; ++j) {
         sum += offDiagonal[i][j] * x[j];
      }
      x[i] = (b[i] - sum) / diagonal[i];
   });
}

