void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Create a vector of vectors to store the non-zero elements of A
   std::vector<std::vector<COOElement>> A_rows(N);
   for (auto const& element : A) {
      A_rows[element.row].push_back(element);
   }

   // Create a vector of HPX futures to store the results of the parallel computations
   std::vector<hpx::future<double>> results(N);

   // Compute the dot products in parallel
   for (size_t i = 0; i < N; ++i) {
      results[i] = hpx::async([i, &A_rows, &b]() {
         double sum = 0;
         for (auto const& element : A_rows[i]) {
            sum += element.value * b[element.column];
         }
         return sum;
      });
   }

   // Wait for all the futures to complete and store the results in x
   for (size_t i = 0; i < N; ++i) {
      x[i] = results[i].get();
   }
}

