   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal elements of A
   std::vector<double> diag(N, 0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] = a.value;
      }
   }

   // Compute the off-diagonal elements of A
   std::vector<double> off_diag(N, 0);
   for (auto const& a : A) {
      if (a.row != a.column) {
         off_diag[a.row] += a.value;
      }
   }

   // Compute the right-hand side vector b
   std::vector<double> rhs(N, 0);
   for (size_t i = 0; i < N; ++i) {
      rhs[i] = b[i];
      for (auto const& a : A) {
         if (a.row == i) {
            rhs[i] -= a.value * x[a.column];
         }
      }
   }

   // Solve the linear system using Gaussian elimination
   for (size_t i = 0; i < N; ++i) {
      // Divide the i-th row by the diagonal element
      double diag_elem = diag[i];
      if (diag_elem != 0) {
         for (size_t j = 0; j < N; ++j) {
            if (j != i) {
               off_diag[j] -= off_diag[i] * off_diag[j] / diag_elem;
            }
         }
         rhs[i] /= diag_elem;
      }
   }

   // Back-substitution
   for (size_t i = N - 1; i < N; --i) {
      x[i] = rhs[i];
      for (size_t j = i + 1; j < N; ++j) {
         x[i] -= off_diag[j] * x[j];
      }
   }
}

