/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal of A
   std::vector<double> diag(N, 0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] = a.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<double> off_diag(N, 0);
   for (auto const& a : A) {
      if (a.row != a.column) {
         off_diag[a.row] += a.value;
      }
   }

   // Compute the right-hand side of the linear system
   std::vector<double> rhs(N, 0);
   for (size_t i = 0; i < N; ++i) {
      rhs[i] = b[i];
      for (size_t j = 0; j < N; ++j) {
         if (i != j) {
            rhs[i] -= A[i * N + j].value * x[j];
         }
      }
   }

   // Solve the linear system using the Thomas algorithm
   std::vector<double> c(N, 0);
   std::vector<double> d(N, 0);
   c[0] = diag[0];
   d[0] = rhs[0];
   for (size_t i = 1; i < N; ++i) {
      c[i] = diag[i] - off_diag[i] / c[i - 1];
      d[i] = rhs[i] - off_diag[i] * d[i - 1] / c[i - 1];
   }
   x[N - 1] = d[N - 1] / c[N - 1];
   for (size_t i = N - 2; i < N; --i) {
      x[i] = (d[i] - off_diag[i] * x[i + 1]) / c[i];
   }
}

