   d[0] = rhs[0];
   for (size_t i = 1; i < N; ++i) {
      c[i] = diag[i] - off_diag[i] / c[i - 1];
      d[i] = rhs[i] - off_diag[i] * d[i - 1] / c[i - 1];
   }
   x[N - 1] = d[N - 1] / c[N - 1];
   for (size_t i = N - 2; i < N; --i) {
      x[i] = (d[i] - off_diag[i] * x[i + 1]) / c[i];
   }
}

