void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal of A
   std::vector<double> diag(N, 0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] = a.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<std::vector<double>> off_diag(N, std::vector<double>(N, 0));
   for (auto const& a : A) {
      if (a.row != a.column) {
         off_diag[a.row][a.column] = a.value;
      }
   }

   // Compute the solution in parallel
   hpx::parallel::for_loop(0, N, [&](size_t i) {
      double sum = 0;
      for (size_t j = 0; j < N; ++j) {
         sum += off_diag[i][j] * x[j];
      }
      x[i] = (b[i] - sum) / diag[i];
   });
}

