void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to all zeros
   x.resize(N, 0.0);

   // Create a parallel for loop to compute the dot product of each row of A with x
   hpx::parallel::for_loop(0, N, [&](size_t i) {
      double sum = 0.0;
      for (auto const& element : A) {
         if (element.row == i) {
            sum += element.value * x[element.column];
         }
      }
      x[i] = (b[i] - sum) / A[i].value;
   });
}

