void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0.0);

   // Create a vector of vectors to store the non-zero elements of each row of A
   std::vector<std::vector<COOElement>> row_elements(N);
   for (auto const& element : A) {
      row_elements[element.row].push_back(element);
   }

   // Compute the dot product of each row of A with x
   std::vector<double> row_dot_products(N, 0.0);
   hpx::parallel::for_each(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : row_elements[i]) {
         row_dot_products[i] += element.value * x[element.column];
      }
   });

   // Compute the dot product of each row of A with b
   std::vector<double> row_b_dot_products(N, 0.0);
   hpx::parallel::for_each(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : row_elements[i]) {
         row_b_dot_products[i] += element.value * b[element.column];
      }
   });

   // Compute the new value of x
   hpx::parallel::for_each(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      x[i] = (row_b_dot_products[i] - row_dot_products[i]) / row_elements[i].size();
   });
}

