void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Create a vector of vectors to store the non-zero elements of each row of A
   std::vector<std::vector<COOElement>> row_elements(N);
   for (auto const& element : A) {
      row_elements[element.row].push_back(element);
   }

   // Create a vector to store the partial sums of the non-zero elements of each row of A
   std::vector<double> row_sums(N, 0);

   // Compute the partial sums in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : row_elements[i]) {
         row_sums[i] += element.value;
      }
   });

   // Create a vector to store the partial sums of the non-zero elements of each column of A
   std::vector<double> column_sums(N, 0);

   // Compute the partial sums in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : row_elements[i]) {
         column_sums[element.column] += element.value;
      }
   });

   // Create a vector to store the diagonal elements of A
   std::vector<double> diagonal_elements(N, 0);

   // Compute the diagonal elements in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : row_elements[i]) {
         if (element.row == element.column) {
            diagonal_elements[i] = element.value;
         }
      }
   });

   // Create a vector to store the solution x
   std::vector<double> solution(N, 0);

   // Compute the solution in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      double sum = 0;
      for (auto const& element : row_elements[i]) {
         if (element.row != element.column) {
            sum += element.value * solution[element.column];
         }
      }
      solution[i] = (b[i] - sum) / diagonal_elements[i];
   });

   // Copy the solution to the output vector
   x = solution;
}

