   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal of A
   std::vector<double> diagonal(N, 0);
   for (auto const& element : A) {
      if (element.row == element.column) {
         diagonal[element.row] = element.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<double> offDiagonal(N, 0);
   for (auto const& element : A) {
      if (element.row != element.column) {
         offDiagonal[element.row] += element.value;
      }
   }

   // Compute the right-hand side
   std::vector<double> rhs(N, 0);
   for (size_t i = 0; i < N; ++i) {
      rhs[i] = b[i];
      for (size_t j = 0; j < N; ++j) {
         if (i != j) {
            rhs[i] -= offDiagonal[j] * x[j];
         }
      }
      rhs[i] /= diagonal[i];
   }

   // Copy the result to x
   x = rhs;
}

