   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0.0);

   // Compute the diagonal of A
   std::vector<double> diag(N, 0.0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] = a.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<double> off_diag(N, 0.0);
   for (auto const& a : A) {
      if (a.row != a.column) {
         off_diag[a.row] += a.value;
      }
   }

   // Compute the right-hand side
   std::vector<double> rhs(N, 0.0);
   for (size_t i = 0; i < N; ++i) {
      rhs[i] = b[i];
      for (size_t j = 0; j < N; ++j) {
         if (i != j) {
            rhs[i] -= A[i*N + j].value * x[j];
         }
      }
   }

   // Solve the system using Gauss-Seidel iteration
   for (size_t i = 0; i < N; ++i) {
      x[i] = rhs[i] / diag[i];
      for (size_t j = 0; j < N; ++j) {
         if (i != j) {
            rhs[j] -= off_diag[j] * x[i];
         }
      }
   }
}

