void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Create a vector of vectors to store the non-zero elements of each row of A
   std::vector<std::vector<COOElement>> row_elements(N);
   for (auto const& element : A) {
      row_elements[element.row].push_back(element);
   }

   // Create a vector of HPX futures to store the results of each row
   std::vector<hpx::future<double>> row_results(N);

   // Compute the results of each row in parallel
   for (size_t i = 0; i < N; ++i) {
      row_results[i] = hpx::async([i, &row_elements, &b, &x] {
         double sum = 0;
         for (auto const& element : row_elements[i]) {
            sum += element.value * x[element.column];
         }
         return sum - b[i];
      });
   }

   // Wait for all the futures to complete
   for (size_t i = 0; i < N; ++i) {
      row_results[i].wait();
   }

   // Compute the final result
   for (size_t i = 0; i < N; ++i) {
      x[i] = -row_results[i].get() / A[i].value;
   }
}

