*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the diagonal elements of A
   std::vector<double> diag(N, 0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] += a.value;
      }
   }

   // Compute the off-diagonal elements of A
   std::vector<double> offDiag(N, 0);
   for (auto const& a : A) {
      if (a.row != a.column) {
         offDiag[a.row] += a.value;
      }
   }

   // Compute the right-hand side vector b
   std::vector<double> rhs(N, 0);
   for (size_t i = 0; i < N; ++i) {
      rhs[i] = b[i];
      for (size_t j = 0; j < N; ++j) {
         if (i != j) {
            rhs[i] -= offDiag[j] * x[j];
         }
      }
      rhs[i] /= diag[i];
   }

   // Copy the result to x
   x = rhs;
}

