   std::vector<double> diag(N, 0.0);
   for (auto const& a : A) {
      if (a.row == a.column) {
         diag[a.row] = a.value;
      }
   }

   // Compute the off-diagonal of A
   std::vector<std::vector<double>> offDiag(N, std::vector<double>(N, 0.0));
   for (auto const& a : A) {
      if (a.row != a.column) {
         offDiag[a.row][a.column] = a.value;
      }
   }

   // Compute the solution in parallel
   hpx::parallel::for_loop(0, N, [&](size_t i) {
      double sum = 0.0;
      for (size_t j = 0; j < N; ++j) {
         sum += offDiag[i][j] * x[j];
      }
      x[i] = (b[i] - sum) / diag[i];
   });
}

