void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Create a vector of vectors to store the non-zero elements of each row of A
   std::vector<std::vector<COOElement>> A_rows(N);
   for (auto const& element : A) {
      A_rows[element.row].push_back(element);
   }

   // Create a vector of vectors to store the non-zero elements of each column of A
   std::vector<std::vector<COOElement>> A_columns(N);
   for (auto const& element : A) {
      A_columns[element.column].push_back(element);
   }

   // Create a vector to store the diagonal elements of A
   std::vector<double> A_diagonal(N);
   for (auto const& element : A) {
      if (element.row == element.column) {
         A_diagonal[element.row] = element.value;
      }
   }

   // Create a vector to store the result of the matrix-vector multiplication Ax
   std::vector<double> Ax(N);

   // Create a vector to store the result of the matrix-vector multiplication A^Tb
   std::vector<double> A_T_b(N);

   // Compute Ax in parallel
   hpx::parallel::for_each(hpx::parallel::par, 0, N, [&](size_t i) {
      double sum = 0;
      for (auto const& element : A_rows[i]) {
         sum += element.value * x[element.column];
      }
      Ax[i] = sum;
   });

   // Compute A^Tb in parallel
   hpx::parallel::for_each(hpx::parallel::par, 0, N, [&](size_t i) {
      double sum = 0;
      for (auto const& element : A_columns[i]) {
         sum += element.value * b[element.row];
      }
      A_T_b[i] = sum;
   });

   // Compute x in parallel
   hpx::parallel::for_each(hpx::parallel::par, 0, N, [&](size_t i) {
      x[i] = (A_T_b[i] - Ax[i]) / A_diagonal[i];
   });
}

