void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the number of non-zero elements in each row of A
   std::vector<size_t> row_counts(N, 0);
   for (auto const& element : A) {
      row_counts[element.row]++;
   }

   // Compute the row pointers for A
   std::vector<size_t> row_pointers(N + 1, 0);
   for (size_t i = 1; i < N + 1; i++) {
      row_pointers[i] = row_pointers[i - 1] + row_counts[i - 1];
   }

   // Compute the column indices and values for A
   std::vector<size_t> column_indices(A.size());
   std::vector<double> values(A.size());
   for (size_t i = 0; i < A.size(); i++) {
      column_indices[i] = A[i].column;
      values[i] = A[i].value;
   }

   // Compute the solution in parallel
   hpx::parallel::for_loop(0, N, [&](size_t i) {
      double sum = 0;
      for (size_t j = row_pointers[i]; j < row_pointers[i + 1]; j++) {
         sum += values[j] * x[column_indices[j]];
      }
      x[i] = (b[i] - sum) / values[row_pointers[i]];
   });
}

