   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Create a vector of vectors to store the non-zero elements of each row of A
   std::vector<std::vector<COOElement>> A_rows(N);
   for (auto const& element : A) {
      A_rows[element.row].push_back(element);
   }

   // Compute the dot product of each row of A with x
   std::vector<double> dot_products(N, 0);
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (auto const& element : A_rows[i]) {
         dot_products[i] += element.value * x[element.column];
      }
   });

   // Compute the residual vector b - Ax
   std::vector<double> residual(N, 0);
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      residual[i] = b[i] - dot_products[i];
   });

   // Solve the linear system Ax=b using the Jacobi method
   std::vector<double> x_new(N, 0);
   double tolerance = 1e-6;
   size_t max_iterations = 1000;
   for (size_t iteration = 0; iteration < max_iterations; ++iteration) {
      hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
         double sum = 0;
         for (auto const& element : A_rows[i]) {
            if (element.column != i) {
               sum += element.value * x[element.column];
            }
         }
         x_new[i] = (residual[i] - sum) / A_rows[i][0].value;
      });

      // Check for convergence
      double error = 0;
      hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
         error += std::abs(x_new[i] - x[i]);
      });
      if (error < tolerance) {
         break;
      }

      // Update x
      x = x_new;
   }
}

