*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Initialize x to zero
   x.resize(N, 0);

   // Compute the number of non-zero elements in each row of A
   std::vector<size_t> row_counts(N, 0);
   for (auto const& element : A) {
      row_counts[element.row]++;
   }

   // Create a vector of vectors to store the non-zero elements in each row of A
   std::vector<std::vector<COOElement>> row_elements(N);
   for (auto const& element : A) {
      row_elements[element.row].push_back(element);
   }

   // Compute the solution in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      // Compute the sum of the non-zero elements in row i
      double sum = 0;
      for (auto const& element : row_elements[i]) {
         sum += element.value * x[element.column];
      }

      // Compute the solution for row i
      x[i] = (b[i] - sum) / row_counts[i];
   });
}

