   // Initialize y to beta*y
   std::fill(y.begin(), y.end(), beta);

   // Compute y = alpha*A*x + beta*y in parallel
   hpx::parallel::for_each(hpx::parallel::par, 0, M, [&](size_t i) {
      for (size_t j = 0; j < N; ++j) {
         for (auto const& a : A) {
            if (a.row == i && a.column == j) {
               y[i] += alpha * a.value * x[j];
               break;
            }
         }
      }
   });
}

