void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
   // Create a vector of vectors to store the partial sums for each row
   std::vector<std::vector<double>> partial_sums(M);

   // Create a vector of HPX futures to store the partial sums for each row
   std::vector<hpx::future<std::vector<double>>> partial_sums_futures(M);

   // Create a vector of HPX futures to store the final results for each row
   std::vector<hpx::future<double>> results(M);

   // Compute the partial sums for each row in parallel
   for (size_t i = 0; i < M; ++i) {
      partial_sums_futures[i] = hpx::async([=]() {
         std::vector<double> partial_sum(N, 0.0);
         for (auto const& element : A) {
            if (element.row == i) {
               partial_sum[element.column] += element.value * x[element.column];
            }
         }
         return partial_sum;
      });
   }

   // Wait for all the partial sums to be computed
   for (size_t i = 0; i < M; ++i) {
      partial_sums[i] = partial_sums_futures[i].get();
   }

   // Compute the final results for each row in parallel
   for (size_t i = 0; i < M; ++i) {
      results[i] = hpx::async([=]() {
         double result = beta * y[i];
         for (size_t j = 0; j < N; ++j) {
            result += alpha * partial_sums[i][j];
         }
         return result;
      });
   }

   // Wait for all the final results to be computed
   for (size_t i = 0; i < M; ++i) {
      y[i] = results[i].get();
   }
}

