      partial_sums_futures[i] = hpx::async([=]() {
         std::vector<double> partial_sum(N, 0.0);
         for (auto const& element : A) {
            if (element.row == i) {
               partial_sum[element.column] += element.value * x[element.column];
            }
         }
         return partial_sum;
      });
   }

   // Wait for all the partial sums to be computed
   for (size_t i = 0; i < M; ++i) {
      partial_sums[i] = partial_sums_futures[i].get();
   }

   // Compute the final results for each row in parallel
   for (size_t i = 0; i < M; ++i) {
      results[i] = hpx::async([=]() {
         double result = beta * y[i];
         for (size_t j = 0; j < N; ++j) {
            result += alpha * partial_sums[i][j];
         }
         return result;
      });
   }

   // Wait for all the final results to be computed
   for (size_t i = 0; i < M; ++i) {
      y[i] = results[i].get();
   }
}

