void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
   // Create a vector of vectors to store the non-zero values of A
   std::vector<std::vector<double>> A_values(M, std::vector<double>(N, 0));

   // Fill A_values with the non-zero values of A
   for (auto const& element : A) {
      A_values[element.row][element.column] = element.value;
   }

   // Compute y = alpha*A*x + beta*y in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
      double sum = 0;
      for (size_t j = 0; j < N; ++j) {
         sum += A_values[i][j] * x[j];
      }
      y[i] = alpha * sum + beta * y[i];
   });
}

