void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
   // Create a vector of vectors to store the partial sums for each row
   std::vector<std::vector<double>> partial_sums(M, std::vector<double>(N, 0.0));

   // Compute the partial sums in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
      for (size_t j = 0; j < N; ++j) {
         for (auto const& element : A) {
            if (element.row == i && element.column == j) {
               partial_sums[i][j] += alpha * element.value * x[j];
            }
         }
      }
   });

   // Compute the final result
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, M, [&](size_t i) {
      y[i] = beta * y[i];
      for (size_t j = 0; j < N; ++j) {
         y[i] += partial_sums[i][j];
      }
   });
}

