void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
   // Initialize L and U to identity matrices
   L.resize(N*N, 0);
   U.resize(N*N, 0);
   for (size_t i = 0; i < N; i++) {
      L[i*N + i] = 1;
      U[i*N + i] = 1;
   }

   // Factorize A into L and U
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, A.size(), [&](size_t i) {
      size_t row = A[i].row;
      size_t column = A[i].column;
      double value = A[i].value;

      // Update L
      for (size_t j = 0; j < column; j++) {
         L[row*N + j] += L[column*N + j] * value;
      }

      // Update U
      for (size_t j = column; j < N; j++) {
         U[row*N + j] += U[column*N + j] * value;
      }

      // Update L and U
      for (size_t j = column + 1; j < N; j++) {
         L[row*N + j] += L[column*N + j] * value;
         U[row*N + j] += U[column*N + j] * value;
      }
   });
}

