void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
   // Initialize L and U to zero
   L.resize(N * N, 0);
   U.resize(N * N, 0);

   // Compute L and U in parallel
   hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&](size_t i) {
      for (size_t j = 0; j < N; ++j) {
         // Compute L[i][j]
         double sum = 0;
         for (size_t k = 0; k < i; ++k) {
            sum += L[i * N + k] * U[k * N + j];
         }
         L[i * N + j] = (A[i * N + j].value - sum) / U[i * N + i];

         // Compute U[i][j]
         sum = 0;
         for (size_t k = 0; k < i; ++k) {
            sum += L[i * N + k] * U[k * N + j];
         }
         U[i * N + j] = A[i * N + j].value - sum;
      }
   });
}

